const UA = 'SEC-RAG-Bot your-name your-email@example.com';
const COMPANIES = {"AAPL": {"name": "Apple", "cik": 320193}, "MSFT": {"name": "Microsoft", "cik": 789019}, "NVDA": {"name": "NVIDIA", "cik": 1045810}, "GOOGL": {"name": "Alphabet (Google)", "cik": 1652044}, "AMZN": {"name": "Amazon", "cik": 1018724}, "META": {"name": "Meta Platforms", "cik": 1326801}, "AVGO": {"name": "Broadcom", "cik": 1730168}, "TSLA": {"name": "Tesla", "cik": 1318605}, "ORCL": {"name": "Oracle", "cik": 1341439}, "NFLX": {"name": "Netflix", "cik": 1065280}, "AMD": {"name": "Advanced Micro Devices", "cik": 2488}, "CRM": {"name": "Salesforce", "cik": 1108524}, "ADBE": {"name": "Adobe", "cik": 796343}, "CSCO": {"name": "Cisco", "cik": 858877}, "IBM": {"name": "IBM", "cik": 51143}, "INTU": {"name": "Intuit", "cik": 896878}, "QCOM": {"name": "Qualcomm", "cik": 804328}, "TXN": {"name": "Texas Instruments", "cik": 97476}, "NOW": {"name": "ServiceNow", "cik": 1373715}, "PLTR": {"name": "Palantir", "cik": 1321655}};
const only = ($('Ingest Webhook').first().json.body || {}).tickers;
const out = [];
for (const [ticker, c] of Object.entries(COMPANIES)) {
  if (Array.isArray(only) && only.length && !only.includes(ticker)) continue;
  const cik10 = String(c.cik).padStart(10, '0');
  const sub = await this.helpers.httpRequest({ url: 'https://data.sec.gov/submissions/CIK' + cik10 + '.json', headers: { 'User-Agent': UA }, json: true, timeout: 30000 });
  const r = sub.filings.recent;
  for (const form of ['10-K', '10-Q']) {
    const i = r.form.indexOf(form);
    if (i === -1) continue;
    const acc = r.accessionNumber[i];
    out.push({ json: { ticker, company: c.name, form, filingDate: r.filingDate[i], reportDate: r.reportDate[i] || '',
      accession: acc, url: 'https://www.sec.gov/Archives/edgar/data/' + c.cik + '/' + acc.replace(/-/g, '') + '/' + r.primaryDocument[i] } });
  }
  await new Promise(res => setTimeout(res, 300));
}
return out;

const UA = 'SEC-RAG-Bot your-name your-email@example.com';
const MAX = 350000, MIN = 20000;
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  try {
    const html = await this.helpers.httpRequest({ url: m.url, headers: { 'User-Agent': UA }, encoding: 'text', json: false, timeout: 120000 });
    const text = String(html)
      .replace(/<ix:header>[\s\S]*?<\/ix:header>/gi, ' ')
      .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<\/(p|div|tr|li|h[1-6])>/gi, '\n').replace(/<br\s*\/?>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;|&#160;|&#xa0;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"')
      .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
      .replace(/[ \t ]+/g, ' ').replace(/ ?\n ?/g, '\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, MAX);
    if (text.length < MIN) { out.push({ json: { ...m, ok: false, reason: 'too little text: ' + text.length } }); continue; }
    out.push({ json: { ...m, ok: true, chars: text.length },
      binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/plain', fileName: m.ticker + '_' + m.form + '_' + m.filingDate + '.txt' } } });
  } catch (e) { out.push({ json: { ...m, ok: false, reason: String(e.message || e).slice(0, 200) } }); }
  await new Promise(res => setTimeout(res, 250));
}
return out;

const SIZE = 1500, OVERLAP = 200, BATCH = 96;
const m = $input.first().json;
const text = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const docs = [];
for (let start = 0, i = 0; start < text.length; start += SIZE - OVERLAP, i++) {
  let end = Math.min(text.length, start + SIZE);
  if (end < text.length) { const cut = text.lastIndexOf('\n', end); if (cut > start + SIZE / 2) end = cut; }   // prefer paragraph breaks
  const chunk = text.slice(start, end).trim();
  if (chunk.length > 80) docs.push({ _id: [m.ticker, m.form, m.filingDate, i].join('-'), chunk_text: chunk,
    ticker: m.ticker, company: m.company, form: m.form, filingDate: m.filingDate, reportDate: m.reportDate || '', url: m.url,
    source: m.ticker + ' ' + m.form + ' (' + m.filingDate + ')' });
  if (end >= text.length) break;
}
const out = [];
for (let b = 0; b < docs.length; b += BATCH) out.push({ json: { ticker: m.ticker, form: m.form, n: docs.length, documents: docs.slice(b, b + BATCH) } });
return out;
